"""Read-only synthetic SESSION-001 characterization from an explicit Git export."""
import asyncio
from dataclasses import asdict
import hashlib
import json
import os
from pathlib import Path
import subprocess
import sys


async def capture(source, revision):
    root = Path.cwd().resolve()
    env = dict(os.environ, GIT_OPTIONAL_LOCKS='0')
    git = lambda *a: subprocess.check_output(['git', '-C', str(root), *a], env=env)
    revision = git('rev-parse', '--verify', revision + '^{commit}').decode().strip()
    expected = {}
    for line in git('ls-tree', '-r', revision, '--', 'packages').decode().splitlines():
        header, name = line.split('\t', 1)
        if '/src/' in name:
            expected[name] = header.split()[2]
    actual = {str(f.relative_to(source)): f for tree in (source / 'packages').glob('*/src') for f in tree.rglob('*') if f.is_file()}
    if set(actual) != set(expected):
        raise RuntimeError('Source inventory differs from Git')
    for name, blob in expected.items():
        if actual[name].read_bytes() != git('cat-file', 'blob', blob):
            raise RuntimeError('Source byte drift: ' + name)
    roots = [f.resolve() for f in sorted((source / 'packages').glob('*/src'))]
    sys.path[:0] = [str(f) for f in roots]
    from friday_chat.commands.contracts import CommandContext, CommandMetadata
    from friday_chat.commands.registry import CommandRegistry, _clear_handler, _history_handler, build_default_registry

    rows = []
    marker = CommandMetadata('unused', 'Unused', 'unused', '/unused')

    class History(list):
        def __init__(self, values, events, failure=None):
            super().__init__(values)
            self.events = events
            self.failure = failure

        def clear(self):
            self.events.append('history.clear')
            if self.failure is not None:
                raise self.failure
            super().clear()

    class Context:
        def __init__(self, history, events, runtime=None, runtime_failure=None):
            self.history = history
            self.events = events
            self._runtime = runtime
            self.runtime_failure = runtime_failure
            self.exit_requested = False

        @property
        def runtime(self):
            self.events.append('runtime.read')
            if self.runtime_failure is not None:
                raise self.runtime_failure
            return self._runtime

    class Memory:
        def __init__(self, history, events, returned=True, failure=None):
            self.history, self.events, self.returned, self.failure = history, events, returned, failure

        async def clear_session_memory(self):
            self.events.append('memory.clear:history=' + json.dumps(self.history))
            if self.failure is not None:
                raise self.failure
            return self.returned

    class Runtime:
        def __init__(self, memory):
            self.memory = memory

    def result(value):
        data = asdict(value)
        data['ui_effects'] = [effect.value for effect in value.ui_effects]
        return data

    for label, turns in [('empty', []), ('one', [('hello', 'world')]), ('ordered', [('second', 'B'), ('first', 'A')]), ('unicode-newlines', [('Å\nuser', '答\nreply')]), ('formatted-values', [(False, None), (7, ['x'])]), ('malformed-short', [('only-one',)]), ('malformed-long', [('a', 'b', 'c')])]:
        events = []
        history = History(turns, events)
        context = Context(history, events, runtime_failure=RuntimeError('history touched runtime'))
        row = {'case': 'history:' + label, 'turns': turns, 'args': ['ignored', '"quoted"']}
        try:
            row['result'] = result(await _history_handler(context, tuple(row['args']), marker))
        except Exception as error:
            row['exception'] = {'type': type(error).__name__, 'message': str(error)}
        row['events'], row['history_after'] = events, list(history)
        rows.append(row)

    for label in ['no-runtime', 'memory-true', 'memory-false', 'memory-exception', 'memory-cancel', 'history-exception', 'runtime-exception']:
        events = []
        failure = asyncio.CancelledError('cancelled') if label == 'memory-cancel' else RuntimeError(label)
        history = History([('hello', 'world')], events, failure if label == 'history-exception' else None)
        memory = Memory(history, events, returned=label != 'memory-false', failure=failure if label in ('memory-exception', 'memory-cancel') else None)
        context = Context(history, events, None if label == 'no-runtime' else Runtime(memory), failure if label == 'runtime-exception' else None)
        row = {'case': 'clear:' + label, 'args': ['ignored']}
        try:
            row['result'] = result(await _clear_handler(context, ('ignored',), marker))
        except BaseException as error:
            row['exception'] = {'type': type(error).__name__, 'message': str(error), 'same_object': error is failure}
        row['events'], row['history_after'] = events, list(history)
        rows.append(row)

    events = []
    history = History([('hello', 'world')], events)
    entered, release = asyncio.Event(), asyncio.Event()

    class BlockingMemory:
        async def clear_session_memory(self):
            events.append('memory.enter')
            entered.set()
            await release.wait()
            events.append('memory.return')
            return False

    task = asyncio.create_task(_clear_handler(Context(history, events, Runtime(BlockingMemory())), (), marker))
    await entered.wait()
    during = {'history': list(history), 'task_done': task.done(), 'events': list(events)}
    release.set()
    completed = await task
    rows.append({'case': 'clear:await-order', 'during_await': during, 'result': result(completed), 'events': events})

    registry = build_default_registry()
    for text in ['/history', '/HiStOrY ignored', '/history "quoted words"', '/clear ignored', '/ClEaR\tmore', '//history', '/ history', ' /clear']:
        context = CommandContext(history=[('hello', 'world')])
        handled, response = await registry.execute(text, context)
        rows.append({'case': 'dispatch:' + text, 'handled': handled, 'result': None if response is None else result(response), 'history_after': context.history, 'exit_requested': context.exit_requested})

    for name, handler in [('history', _history_handler), ('clear', _clear_handler)]:
        custom = CommandRegistry()
        custom.register('renamed', description='Renamed', category='test', handler=handler)
        context = CommandContext(history=[('hello', 'world')])
        handled, response = await custom.execute('/renamed extra', context)
        rows.append({'case': 'renamed:' + name, 'handled': handled, 'result': result(response), 'history_after': context.history})

    origins = {}
    for name, module in tuple(sys.modules.items()):
        if name.startswith('friday') and module is not None:
            file = getattr(module, '__file__', None)
            paths = ([file] if file else []) + list(getattr(module, '__path__', ()))
            if not paths or not all(any(Path(path).resolve().is_relative_to(tree) for tree in roots) for path in paths):
                raise RuntimeError('Loaded module escaped source export: ' + name)
            origins[name] = [str(Path(path).resolve()) for path in paths]
    return {'provenance': {'revision': revision, 'capture_sha256': hashlib.sha256(Path(__file__).read_bytes()).hexdigest(), 'source_files': len(actual), 'source_inventory_sha256': hashlib.sha256(json.dumps(expected, sort_keys=True).encode()).hexdigest(), 'origins': origins}, 'metadata': {name: asdict(registry.commands[name]) for name in ('clear', 'history')}, 'cases': rows}


if __name__ == '__main__':
    source, output, revision = Path(sys.argv[1]).resolve(), Path(sys.argv[2]).resolve(), sys.argv[3]
    if output.exists() or output.is_relative_to(Path.cwd().resolve()) or output.is_relative_to(source):
        raise SystemExit('Use a fresh output outside repository and export')
    document = asyncio.run(capture(source, revision))
    output.write_text(json.dumps(document, indent=2) + '\n')
    print('Captured', len(document['cases']), 'session cases and two exact metadata records')

"""Exact JSON diagnostics comparison with pinned baseline/capture identities."""
import copy
import hashlib
import json
from pathlib import Path
import sys

def same(left, right):
    if type(left) is not type(right):
        return False
    if isinstance(left, dict):
        return left.keys() == right.keys() and all(same(left[k], right[k]) for k in left)
    if isinstance(left, list):
        return len(left) == len(right) and all(same(a,b) for a,b in zip(left,right,strict=True))
    return left == right

def compare(raw, candidate, baseline_sha, capture_sha, allow_cache_refusal=False):
    if hashlib.sha256(raw).hexdigest() != baseline_sha:
        raise ValueError('Baseline hash mismatch')
    base = json.loads(raw)
    for document in (base, candidate):
        if document['provenance']['capture_sha256'] != capture_sha:
            raise ValueError('Capture identity mismatch')
    if not same(base['metadata'],candidate['metadata']):
        raise ValueError('Diagnostics differ: metadata')
    if len(base['cases']) != len(candidate['cases']):
        raise ValueError('Diagnostics row count differs')
    exceptions = {name+':undeclared-cache:'+kind for name in ('context','prompt') for kind in ('truthy-int','truthy-list')}
    for old, new in zip(base['cases'],candidate['cases'],strict=True):
        if same(old,new):
            continue
        if allow_cache_refusal and old['case'] in exceptions:
            expected = copy.deepcopy(old)
            del expected['result']
            expected['exception'] = {'type':'TypeError'}
            observed = copy.deepcopy(new)
            if isinstance(observed.get('exception'),dict):
                observed['exception'].pop('message',None)
            if same(expected,observed):
                continue
        raise ValueError('Diagnostics differ: '+old['case'])

def selftest():
    b={'provenance':{'capture_sha256':'program'},'metadata':{'name':'context'},'cases':[{'case':'control','flag':False,'n':0,'events':['read','write']}]}
    raw=json.dumps(b).encode(); digest=hashlib.sha256(raw).hexdigest()
    compare(raw,b,digest,'program')
    controls=[]
    for label in ('baseline','program','bool-int','row','order','metadata','extra'):
        v=copy.deepcopy(b); r=raw
        if label=='baseline': r += b' '
        elif label=='program': v['provenance']['capture_sha256']='other'
        elif label=='bool-int': v['cases'][0]['flag']=0
        elif label=='row': v['cases'][0]['n']=1
        elif label=='order': v['cases'][0]['events'].reverse()
        elif label=='metadata': v['metadata']['name']='prompt'
        elif label=='extra': v['cases'].append({})
        try: compare(r,v,digest,'program')
        except ValueError: controls.append(label)
        else: raise RuntimeError('Comparator accepted '+label)
    boundary=copy.deepcopy(b)
    boundary['cases']=[{'case':'context:undeclared-cache:truthy-int','result':{'output':7},'events':['context.last_context']}]
    raw2=json.dumps(boundary).encode(); sha2=hashlib.sha256(raw2).hexdigest()
    refusal=copy.deepcopy(boundary)
    del refusal['cases'][0]['result']
    refusal['cases'][0]['exception']={'type':'TypeError','message':'Expected a string'}
    compare(raw2,refusal,sha2,'program',True)
    for label, allow, candidate in [('boundary-without-approval',False,refusal),('wrong-boundary-exception',True,copy.deepcopy(refusal)),('boundary-side-effect',True,copy.deepcopy(refusal))]:
        if label=='wrong-boundary-exception': candidate['cases'][0]['exception']['type']='ValueError'
        if label=='boundary-side-effect': candidate['cases'][0]['events'].append('write')
        try: compare(raw2,candidate,sha2,'program',allow)
        except ValueError: controls.append(label)
        else: raise RuntimeError('Comparator accepted '+label)
    print('Comparator refused:', ', '.join(controls))

if __name__=='__main__':
    if sys.argv[1:] == ['--selftest']:
        selftest()
    else:
        args=sys.argv[1:]
        allow=args[-1:] == ['--allow-declared-cache-refusal']
        if allow: args=args[:-1]
        baseline,candidate,digest,program = args
        compare(Path(baseline).read_bytes(),json.loads(Path(candidate).read_text()),digest,program,allow)
        print('Six metadata records and all diagnostic cases match exactly')

"""Type-aware comparison of frozen SESSION-001 observations."""
import copy
import hashlib
import json
from pathlib import Path
import sys


def equal(a, b):
    if type(a) is not type(b):
        return False
    if isinstance(a, dict):
        return a.keys() == b.keys() and all(equal(a[key], b[key]) for key in a)
    if isinstance(a, list):
        return len(a) == len(b) and all(equal(left, right) for left, right in zip(a, b))
    return a == b


def compare(before, after, program_hash):
    for document in (before, after):
        if document.get('provenance', {}).get('capture_sha256') != program_hash:
            raise RuntimeError('Capture program identity differs')
    if not equal(before['metadata'], after['metadata']) or not equal(before['cases'], after['cases']):
        raise RuntimeError('Session observations differ')


def selftest():
    sample = {'provenance': {'capture_sha256': 'a' * 64}, 'metadata': {'clear': {'name': 'clear'}}, 'cases': [{'case': 'a', 'handled': True, 'events': ['clear', 'memory']}]}
    compare(sample, copy.deepcopy(sample), 'a' * 64)
    mutations = []
    for change in ('bool-int', 'event-order', 'extra-case', 'metadata', 'missing-identity', 'changed-identity'):
        mutated = copy.deepcopy(sample)
        if change == 'bool-int':
            mutated['cases'][0]['handled'] = 1
        elif change == 'event-order':
            mutated['cases'][0]['events'].reverse()
        elif change == 'extra-case':
            mutated['cases'].append({'case': 'extra'})
        elif change == 'metadata':
            mutated['metadata']['clear']['name'] = 'renamed'
        elif change == 'missing-identity':
            del mutated['provenance']['capture_sha256']
        else:
            mutated['provenance']['capture_sha256'] = 'b' * 64
        try:
            compare(sample, mutated, 'a' * 64)
        except RuntimeError:
            mutations.append(change)
        else:
            raise RuntimeError('Comparison accepted a changed observation: ' + change)
    print('Comparator identity and six refusal controls passed:', ', '.join(mutations))


if __name__ == '__main__':
    if sys.argv[1:] == ['--selftest']:
        selftest()
    else:
        baseline, after, baseline_hash, program_hash = sys.argv[1:]
        raw = Path(baseline).read_bytes()
        if hashlib.sha256(raw).hexdigest() != baseline_hash:
            raise RuntimeError('Frozen baseline hash differs')
        compare(json.loads(raw), json.loads(Path(after).read_text()), program_hash)
        print('Two session metadata records and all 25 observations match exactly')

