    name: str,
    description: str,
    *,
    required: bool = False,
    default: str | None = None,
    choices: tuple[str, ...] = (),
) -> CommandArgument:
    return CommandArgument(
        name=name,
        description=description,
        required=required,
        default=default,
        choices=choices,
    )


